(function(root){
 'use strict';
 function csv(text){const rows=[];let row=[],cell='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted||cell==='')quoted=!quoted;else cell+=c;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV 引號未完整結束。');row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}
 const headers=['小朋友名字','紀錄種類','練習編號','科目','單元','題號','題型','題目','作答內容','正確答案','是否答對','分數','答對題數','總題數','作答秒數','紀錄編號','裝置作答時間'];
 function fromCSV(text){const rows=csv(text),h=rows.shift()||[];if(headers.some(k=>!h.includes(k)))throw Error('請匯入「作答紀錄」工作表的 CSV，需保留原始欄位。');const get=(r,k)=>r[h.indexOf(k)]||'';const arr=s=>{try{const a=JSON.parse(s);return Array.isArray(a)?a:[s];}catch{return [s];}};return rows.map(r=>{const kind=get(r,'紀錄種類');if(!['逐題作答','練習完成'].includes(kind))throw Error('CSV 含無法辨識的紀錄種類。');return {id:get(r,'紀錄編號'),learner:get(r,'小朋友名字'),kind:kind==='逐題作答'?'answer':'session',sessionId:get(r,'練習編號'),subject:get(r,'科目'),unitName:get(r,'單元'),questionId:get(r,'題號'),questionType:get(r,'題型'),question:get(r,'題目'),selected:arr(get(r,'作答內容')),expected:arr(get(r,'正確答案')),correct:get(r,'是否答對')==='答對',score:Number(get(r,'分數')),right:Number(get(r,'答對題數')),total:Number(get(r,'總題數')),elapsedSeconds:Number(get(r,'作答秒數')),createdAt:get(r,'裝置作答時間')};});}
 function merge(...sources){const map=new Map();for(const e of sources.flat())if(e&&e.id&&e.learner&&['answer','session'].includes(e.kind))map.set(e.id,e);return [...map.values()].sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))||String(a.id).localeCompare(String(b.id)));}
 function grade(e,units){const u=units.find(u=>u.questions.some(q=>q.id===e.questionId));return u?u.grade:Number(e.grade)|| (String(e.unitName).startsWith('三上｜')?3:5);}
 function summary(events){const answers=events.filter(e=>e.kind==='answer'),sessions=events.filter(e=>e.kind==='session'),groups=new Map();for(const e of answers){const key=e.questionId||e.question;const a=groups.get(key)||[];a.push(e);groups.set(key,a);}const wrong=[...groups.values()].filter(a=>a.some(e=>e.correct===false)).map(a=>({latest:a.at(-1),count:a.filter(e=>e.correct===false).length,resolved:a.at(-1).correct===true,attempts:a}));return {answers,sessions,wrong,open:wrong.filter(w=>!w.resolved),accuracy:answers.length?Math.round(answers.filter(e=>e.correct===true).length/answers.length*100):null,days:new Set(answers.map(e=>new Date(e.createdAt).toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'}))).size};}
 const api={csv,fromCSV,merge,grade,summary};if(typeof module==='object')module.exports=api;else root.ParentModel=api;
})(typeof window==='undefined'?globalThis:window);
